}
vec3 milnorNormal(vec3 p){
 const vec2 k=vec2(1,-1);float e=.0012;
 return normalize(k.xyy*milnorMap(p+k.xyy*e).x+k.yyx*milnorMap(p+k.yyx*e).x+k.yxy*milnorMap(p+k.yxy*e).x+k.xxx*milnorMap(p+k.xxx*e).x);
